export async function verifyFixedQuality(w,{control=false,refreshShadow=false,holdFar=false,holdGround=false,hideWater=false}={}){
 const hash=a=>{if(!a)return null;const bytes=new Uint8Array(a.buffer,a.byteOffset,a.byteLength);let h=2166136261;for(const b of bytes)h=Math.imul(h^b,16777619);return h>>>0;};
 const instanceState=w=>({ferns:w.groundDetails.meshes.map(e=>({count:e.mesh.geometry.instanceCount,attributes:Object.fromEntries(['coverageAnchor','coverageData','coverageSlope'].map(k=>[k,hash(e.mesh.geometry.attributes[k].array.subarray(0,e.mesh.geometry.instanceCount*e.mesh.geometry.attributes[k].itemSize))]))})),groups:Object.fromEntries(['colors','shadows'].map(k=>[k,[...w.assetGroups[k]].map(([key,g])=>({key,count:g.mesh.count,matrix:hash(g.mesh.instanceMatrix.array.subarray(0,g.mesh.count*16)),visibility:hash(g.mesh.geometry.attributes.nativeVisibility?.array.subarray(0,g.mesh.count)),source:g.sourceStamp}))]))});
 const c=w.mangroveMaterialCache;if(!c)throw Error('Integrated cache missing');const original=w.quality,samples=[];if(refreshShadow)w.releaseNativeShadow.cache.invalidate();
 const groundConfigure=w.groundDetails?.configureQuality;if(holdGround&&groundConfigure)w.groundDetails.configureQuality=()=>{};
 const farConfigure=w.farVegetation?.configureQuality;if(holdFar&&farConfigure)w.farVegetation.configureQuality=()=>{};
 try{for(const quality of (control?Array(5).fill(original):['media','muy_baja','media','muy_baja','media'])){
  if(control&&refreshShadow)w.releaseNativeShadow.cache.invalidate();
  if(!control)w.qualitySetting(quality);for(let i=0;i<45;i++)await new Promise(requestAnimationFrame);
  const states=[...c.states.values()],ground=[...w.chunks.values()].map(g=>g.children.find(m=>m.userData.ground).material);
  const meshState=[];w.scene.traverse(o=>{if(!o.isMesh)return;let shown=true;for(let p=o;p;p=p.parent)shown&&=p.visible;meshState.push({id:o.id,name:o.name,visible:shown,geometry:o.geometry.id,count:o.count??o.geometry.instanceCount??null,triangles:o.geometry.index?.count??o.geometry.attributes.position?.count,world:o.matrixWorld.toArray(),cast:o.castShadow,receive:o.receiveShadow,materials:(Array.isArray(o.material)?o.material:[o.material]).map(m=>({type:m.type,color:m.color?.getHex(),roughness:m.roughness,metalness:m.metalness,opacity:m.opacity,side:m.side,transparent:m.transparent,key:m.customProgramCacheKey()}))});});
  const hidden=[];if(hideWater){w.scene.traverse(o=>{if(o.isMesh&&(Array.isArray(o.material)?o.material:[o.material]).some(m=>m.userData.paintUniforms)){hidden.push([o,o.visible]);o.visible=false;}});w.render(0);}let capture;try{capture=w.renderer.domElement.toDataURL('image/png').split(',')[1];}finally{for(const [o,visible]of hidden)o.visible=visible;}
  samples.push({quality,instanceState:instanceState(w),meshState,shadowState:{mapSize:w.sun.shadow.mapSize.toArray(),matrix:w.sun.shadow.matrix.toArray(),camera:w.sun.shadow.camera.projectionMatrix.toArray(),native:Object.fromEntries(Object.entries(w.toon.shadowUniforms).map(([k,u])=>[k,u?.value?.toArray?u.value.toArray():u?.value?.isTexture?{texture:u.value.uuid,width:u.value.image?.width,height:u.value.image?.height}:typeof u?.value==='number'?u.value:null]))},water:[...w.materialRegistry.waters].map(([m,u])=>({id:m.id,type:m.type,time:u.uTime.value,uniforms:Object.fromEntries(Object.entries(u).filter(([k,v])=>typeof v.value==='number').map(([k,v])=>[k,v.value]))})),far:w.farVegetation?.stats,shadow:{...w.releaseNativeShadow.cache.stats},entries:c.queue.entries.size,bytes:c.queue.stats.bytes,publications:c.queue.stats.published,hooks:states.reduce((n,s)=>n+s.hooks.size,0),tracked:states.reduce((n,s)=>n+s.record.materials.size,0),unpatched:ground.filter(m=>!states.some(s=>s.hooks.has(m))).length,capture,memory:{...w.renderer.info.memory},glError:w.renderer.getContext().getError()});
 }
 if(samples.some(s=>s.unpatched||s.glError||s.hooks!==s.tracked))throw Error('Quality switch lost cache patch');
 return {control,refreshShadow,holdFar,holdGround,hideWater,samples,scope:'Real quality switches; cache hook ownership and GL validation'};
 }finally{if(holdGround&&groundConfigure)w.groundDetails.configureQuality=groundConfigure;if(holdFar&&farConfigure)w.farVegetation.configureQuality=farConfigure;if(!control)w.qualitySetting(original);}
}
